SELECT json_object('queriedAt',strftime('%Y-%m-%dT%H:%M:%SZ','now'),'cron',json((SELECT json_group_array(json_object('started_at',started_at,'completed_at',completed_at,'job',job,'outcome',outcome)) FROM (SELECT started_at,completed_at,job,outcome FROM cron_runs ORDER BY started_at DESC LIMIT 12))),'ingestion',json((SELECT json_group_array(json_object('key',key,'last_attempt',last_attempt,'last_success',last_success,'data_as_of',data_as_of,'error',error,'failures',failures)) FROM (SELECT key,last_attempt,last_success,data_as_of,error,failures FROM ingestion WHERE key IN ('quote:BTC:binance','quote:BTC:upbit','quote:DOGE:binance','quote:DOGE:upbit','quote:ETH:binance','quote:ETH:upbit') OR key LIKE 'derivatives:BTC:%' OR key LIKE 'derivatives:DOGE:%' OR key LIKE 'derivatives:ETH:%' ORDER BY key))),'backfillState',json((SELECT json_group_array(json_object('key',key,'value',value)) FROM state WHERE key='budget:derivatives-backfill' OR key LIKE 'cursor:derivatives:%')),'briefings',json((SELECT json_group_array(json_object('id',id,'created_at',created_at)) FROM (SELECT id,created_at FROM daily_briefings ORDER BY created_at DESC LIMIT 3)))) AS evidence;
